describe('Conflict Error Handling', () => {
    beforeEach(() => {
        cy.intercept('POST', '/api/records', {
            statusCode: 409,
            body: { message: 'Conflict: Record is stale and cannot be saved.' },
        }).as('saveRecord');
        cy.visit('/records'); // Adjust the URL to your application's records page
    });

    it('should display a conflict error message when saving a stale record', () => {
        cy.get('input[name="recordName"]').type('Stale Record');
        cy.get('button[type="submit"]').click();
        cy.wait('@saveRecord');
        cy.get('.error-message').should('be.visible').and('contain', 'Conflict: Record is stale and cannot be saved.');
    });

    it('should not display the error message when saving a valid record', () => {
        cy.intercept('POST', '/api/records', {
            statusCode: 200,
            body: { message: 'Record saved successfully.' },
        }).as('saveValidRecord');

        cy.get('input[name="recordName"]').type('Valid Record');
        cy.get('button[type="submit"]').click();
        cy.wait('@saveValidRecord');
        cy.get('.error-message').should('not.exist');
    });
});
